#include "unity.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_calculateCentroid_basic_mean_and_group_reset(void) {
    // Setup: create a small array of observations with known values
    observation observations[3];
    observations[0].x = 1.0; observations[0].y = 2.0; observations[0].group = 5;
    observations[1].x = 3.0; observations[1].y = 4.0; observations[1].group = 7;
    observations[2].x = 5.0; observations[2].y = 6.0; observations[2].group = -2;

    cluster centroid;
    centroid.x = 0.0;
    centroid.y = 0.0;
    centroid.count = 0;

    // Test: call function under test
    calculateCentroid(observations, 3, &centroid);

    // Assertions: centroid should be mean of x and y, count should be 3
    TEST_ASSERT_FLOAT_WITHIN(1e-9, 3.0, centroid.x); // (1+3+5)/3 = 3.0
    TEST_ASSERT_FLOAT_WITHIN(1e-9, 4.0, centroid.y); // (2+4+6)/3 = 4.0
    TEST_ASSERT_EQUAL(3, centroid.count);

    // All observation group fields should be set to 0
    for (size_t i = 0; i < 3; ++i) {
        TEST_ASSERT_EQUAL(0, observations[i].group);
    }
    // No dynamic memory to free
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_calculateCentroid_basic_mean_and_group_reset);
    return UNITY_END();
}
